local KTool = CS.Engine.Lib.KTool

local OnOff = CS.Game.OnOff


-- ========================================================


local currentInstance = nil


-- ========================================================




function DreamSpaceStory:__init( onOff_ )
    self.mCamera = DreamSpaceCamera.GetMainCamera()


end


function DreamSpaceStory:__delete()
end



function DreamSpaceStory:Awake()
    if currentInstance == nil then 
        currentInstance = self
    else 
        assert( false, "不允许存在 第二个 DreamSpaceStory 实例" )
    end 
end




function DreamSpaceStory:Start()
    KTool.SetActive(self.controller.gameObject, true);
    assert( self.dreamSpaceTalkingNodeBH )
    self.dreamSpaceTalkingNode = DreamSpaceLuaUtils.GetLuaScr(self.dreamSpaceTalkingNodeBH.gameObject, "Game.DreamSpace.Tools.DreamSpaceTalkingNode" )
    assert( self.dreamSpaceTalkingNode )
    ---
    self.dreamSpaceTalkingNode:Hide()
end



function DreamSpaceStory:OnDestroy()
    currentInstance = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end


function DreamSpaceStory.WaitInstance()
    -- 只等待有限帧
    for i=1,DreamSpaceStates.DelayInitWaitFrames do 
        if isNotNull(currentInstance) then 
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end 
    assert( isNotNull(currentInstance), "始终没能等到 DreamSpaceStory 实例化, 请检查场景" )
end


function DreamSpaceStory.GetInstance()
    return currentInstance
end


-- =========================================== Self ================================================ --



function DreamSpaceStory:PlayStory( storyId_ )
    assert( storyId_ ~= nil )

    local playerComp = ChapterUtils.GetPlayerComp()

    if DreamSpaceStates.isWindowsPlatform == true then 
        -- 解除 鼠标锚点锁定:
        Cursor.lockState = CursorLockMode.None
    end 

    local talksVo = DreamlandUtils.GetDreamlandTalksVo( storyId_ ) -- 对话文本, idx 1-based
    -- 只是简单地将 talksVo 中每行数据 播放一下:
    -- 完全不关心 行与行 之间的自定义次序;

    
    self.dreamSpaceTalkingNode:Show() -- 打开 剧情 ui 面板:

    self.dreamSpaceTalkingNode:SetIsEnd( false )

    for i=1, table.count(talksVo) do
        local vo = talksVo[i]

        -- 替换 PlayerName:
        -- local playerName = vo.PlayerName
        -- if vo.PlayerName == "#playerName" then 
        --     playerName = playerComp.playerDojo.playerName
        -- end 
        -- --- 
        -- local content = ChapterUtils.ReplaceStr(vo.Content, "#playerName", playerComp.playerDojo.playerName)

        -- 等待 本行文本 打印完
        self.dreamSpaceTalkingNode:FreshUI({
            playerName    = ChapterUtils.ReplaceStr(vo.PlayerName, "#playerName", playerComp.playerDojo.playerName),
            talkContent   = ChapterUtils.ReplaceStr(vo.Content,    "#playerName", playerComp.playerDojo.playerName)
        })

        while not self.dreamSpaceTalkingNode:IsFinish() do
            coroutine.yield(Yielders.EndOfFrame)
        end

        
        -- 等待玩家 点击屏幕
        while not self:IsCanPlayNextTalk() do

            if self.dreamSpaceTalkingNode:GetIsEnd() == true then 
                goto continue
            end 

            coroutine.yield(Yielders.EndOfFrame)
        end

    end
    ::continue::


    if DreamSpaceStates.isWindowsPlatform == true then 
        -- 锁定 鼠标锚点:
        Cursor.lockState = CursorLockMode.Locked
    end 

    self.dreamSpaceTalkingNode:Hide() -- 关闭 剧情 ui 面板:
end



function DreamSpaceStory:IsCanPlayNextTalk()
    if isNull(self.dreamSpaceTalkingNode) then
        return true
    end
    return self.dreamSpaceTalkingNode:IsCanPlayNext()
end



return DreamSpaceStory
